    buy_book = []  # List of [arrival_time, price, qty, id]
    sell_book = []  # List of [arrival_time, price, qty, id]
    order_map = {}  # Maps id to (side, arrival_time) for tracking cancellations
    time_counter = 0

    for order in orders:
        time_counter += 1
        order_type = order[0]

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, arrival_time = order_map[order_id]
                if side == 'buy':
                    buy_book = [o for o in buy_book if o[3] != order_id]
                else:
                    sell_book = [o for o in sell_book if o[3] != order_id]
                del order_map[order_id]

        else:
            order_id = order[1]
            side = order[2]
            qty = order[-1]

            if order_type == 'limit':
                price = order[3]
            elif order_type == 'ioc':
                price = order[3]
            else:  # market
                price = None

            remaining_qty = qty

            if side == 'buy':
                # Match against sell_book
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    if order_type == 'market' or sell_book[i][1] <= price:
                        sell_arrival, sell_price, sell_qty, sell_id = sell_book[i]
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_book[i] = (sell_arrival, sell_price, sell_qty - trade_qty, sell_id)
                        if sell_book[i][2] == 0:
                            sell_book.pop(i)
                        else:
                            i += 1
                    else:
                        break

                # Add to buy_book if limit and has remaining
                if order_type == 'limit' and remaining_qty > 0:
                    buy_book.append([time_counter, price, remaining_qty, order_id])
                    buy_book.sort(key=lambda x: (-x[1], x[0]))
                    order_map[order_id] = ('buy', time_counter)

            else:  # side == 'sell'
                # Match against buy_book
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    if order_type == 'market' or buy_book[i][1] >= price:
                        buy_arrival, buy_price, buy_qty, buy_id = buy_book[i]
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_book[i] = (buy_arrival, buy_price, buy_qty - trade_qty, buy_id)
                        if buy_book[i][2] == 0:
                            buy_book.pop(i)
                        else:
                            i += 1
                    else:
                        break

                # Add to sell_book if limit and has remaining
                if order_type == 'limit' and remaining_qty > 0:
                    sell_book.append([time_counter, price, remaining_qty, order_id])
                    sell_book.sort(key=lambda x: (x[1], x[0]))
                    order_map[order_id] = ('sell', time_counter)

    return trades

